        .composite([
        {
            input: mask,
            blend: 'dest-in',
            top: location.top,
            left: location.left,
        },
        {
            input: outline,
            blend: 'over',
            top: location.top,
            left: location.left,
        },
    ]).toBuffer();
    const slider = await sharp(composed).extract({
        left: location.left,
        top: 0,
        width: sizes.PUZZLE,
        height: sizes.HEIGHT,
